function shuffleExamples(){exampleOrder=[...briefExamples].sort(()=>Math.random()-.5);examplePos=0}
function nextExample(){if(examplePos>=exampleOrder.length)shuffleExamples();return 'For example: '+exampleOrder[examplePos++]}
function exampleMotionAllowed(){return !calmMotion.matches&&!['none','calm'].includes(document.documentElement.dataset.motion)}
function rotateExample(){if(!exampleMotionAllowed()||!d.open||describe.hidden||document.activeElement===brief||brief.value)return;const text=nextExample();brief.classList.add('brief-swap');setTimeout(()=>{if(exampleMotionAllowed()&&d.open&&!describe.hidden&&document.activeElement!==brief&&!brief.value)brief.placeholder=text;brief.classList.remove('brief-swap')},240)}
