 async function pollJob(){clearTimeout(jobTimer);try{const r=await fetch('/api/settings/build/job?id='+encodeURIComponent(jobId),{headers:headers()}),data=await r.json();if(!r.ok)throw Error(data.error||'Build status unavailable');paintJob(data);if(data.state==='running'){jobTimer=setTimeout(pollJob,1000);return}if(data.state==='done'&&data.yaml){yaml.value=data.yaml;sections=all;await editFields();step(1);find('builderScopeNotice').textContent='Complete merged app draft. No code was run. Local validation passed; live APIs not tested.';retainedDraftId=data.id;retainedYaml=data.yaml;draftLibrary();status.replaceChildren(el('p','Draft received. Local schema checks passed, not safety verification.'));if(data.local_review?.length)status.append(el('p','Local observations, limited checks: '+data.local_review.join(' ')));if(data.review?.issues?.length)status.append(el('p','Model suggestions, not verification: '+data.review.issues.join(' ')));if(data.review?.setup_notes?.length)status.append(el('p','Before deployment: '+data.review.setup_notes.join(' ')));if(data.review?.review_status==='inconsistent')status.append(el('p',data.review.review_note||'Model review verdict is inconsistent. Human review is still needed.'));else if(data.review?.ready===false)status.append(el('p','The model returned concerns. Check them yourself before saving.'));status.append(el('p','A model can miss unsafe prompts or code. No findings does not establish safety. Review prompts, helper destinations and deployment access before use.'));}else if(data.state==='cancelled')status.textContent='Build cancelled. No files saved.';}catch(e){busy=false;status.textContent=e.message+' Build may still be running; reopen to check.';progress.dataset.jobState='unknown';activity.dataset.state='unknown';activityTitle.textContent='Check build status';activityPart.textContent='Status unavailable. Open to retry.';update()}}
